from code import InteractiveConsole


class KitInteractiveConsole(InteractiveConsole):
    def __init__(self, wait_for_app_ready: bool, locals: dict, *args, **kwargs):
        # Block any locals form this script begin
        allowed = ("__builtins__", "__name__", "console", "pause", "quit")
        locals = {k: v for k, v in locals.items() if k in allowed}
        # Add a way to reach the console object, override the call to quit, and add a pause() function"
        locals["console"] = self
        locals["pause"] = lambda: self.pause()
        locals["quit"] = lambda exit_code = 0: self.quit(exit_code)
        # Save Python's quit function to be callable from the override
        self.__py_quit = quit
        self.__app = self.__get_app(wait_for_app_ready)
        self.paused = False

        super().__init__(locals, *args, **kwargs)

    @staticmethod
    def __get_app(wait_for_app_ready: bool):
        import carb
        import omni.kit.app

        app_ready = None
        app = omni.kit.app.get_app()
        if app and wait_for_app_ready and not app.is_app_ready():
            def app_ready_done(*args, **kwargs):
                nonlocal app_ready
                app_ready = None

            app_ready = carb.eventdispatcher.get_eventdispatcher().observe_event(
                event_name=omni.kit.app.GLOBAL_EVENT_APP_READY,
                on_event=app_ready_done,
                observer_name="kit.python.shell.wait"
            )

            while not app.is_app_ready():
                app.update()

        return app

    @property
    def app(self):
        """Return the app this console is associated with."""
        return self.__app

    def quit(self, exit_code = 0):
        """Post an un-cancellable quit event to the app and exit via Python's quit function"""
        if self.__app:
            self.__app.post_uncancellable_quit(exit_code)
            self.__app.update()
        self.__py_quit(exit_code)

    def pause(self):
        """Stop any internal app.update() calls."""
        self.paused = not self.paused

    def run(self, n: int = 1):
        """Run the kit application loop for the given number of iterations.
        If the console is 'paused' before the iterations are complete, the loop will stop.
        """
        if self.__app:
            for _ in range(n):
                if self.paused:
                    break
                self.__app.update()


    def push(self, *args, **kwargs):
        """Override for InteractiveConsole.push that will update the app once if code was executed."""
        pushed = super().push(*args, **kwargs)
        if pushed == False and not self.paused and self.__app:
            self.__app.update()
        return pushed

    def raw_input(self, prompt="", *args, **kwargs):
        """Override for InteractiveConsole.raw_input to show the update number."""
        if self.__app:
            prompt = f"[kit-update {self.__app.get_update_number()}] {prompt}"

        return super().raw_input(prompt=prompt, *args, **kwargs)

    def interact(self, banner = None, *args, **kwargs):
        """Override for InteractiveConsole.interact: show a banner and start the REPL."""
        def _get_banner(app):
            # BLUE = '\033[94m'
            GREEN = '\033[92m'
            # RED = '\033[91m'
            RESET = '\033[0m'
            YELLOW = '\033[93m'

            import sys
            return (YELLOW + "\n"
                    f"Python {sys.version} on {sys.platform}\n" +
                    'Type "help", "copyright", "credits" or "license" for more information.\n' +
                    GREEN + "\n"
                    f"Kit {app.get_build_version()} ({'Debug' if app.is_debug_build() else 'Release'})\n"
                    + RESET)

        # Default writes to std.err, which is caught by kit -> carb log, so just print the banner
        print(banner or _get_banner(self.__app))
        # Don't allow recursion into this method
        self.interact = None
        return super().interact(banner="", *args, **kwargs)


KitInteractiveConsole(True, locals()).interact()
